async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options});if(!response.ok)throw new Error((await response.json()).error||response.statusText);return response.json()}
const clamp=(value,min,max)=>Math.max(min,Math.min(max,Number(value)||0));
function sanitizeAudioChannel(value={}){const result=neutralAudioChannel();for(const key of AUDIO_FIELDS)result[key]=clamp(value[key],0,1);result.silent=!!value.silent;return result}
function sanitizeAudioState(value={}){return{guitar_a:sanitizeAudioChannel(value.guitar_a),guitar_b:sanitizeAudioChannel(value.guitar_b),interaction:clamp(value.interaction,0,1)}}
function sanitizeAudioTuning(value={}){const result={enabled:value.enabled!==false,active_preset:String(value.active_preset||'Custom').slice(0,80),effect_mappings:{}};for(const [name,defaults] of Object.entries(DEFAULT_AUDIO_TUNING.effect_mappings)){const definition=EFFECT_MAPPING_DEFS[name],incoming=value.effect_mappings?.[name]||value.mappings?.[definition.legacy]||{};result.effect_mappings[name]={enabled:incoming.enabled!==false,source:AUDIO_SOURCES[incoming.source]?incoming.source:defaults.source};for(const [field,[,min,max]] of Object.entries(MAPPING_FIELDS))result.effect_mappings[name][field]=clamp(incoming[field]??defaults[field],min,max)}result.band_logo=sanitizeBandLogo(value.band_logo);return result}
function sanitizeBandLogo(value={}){const incoming=value||{},result={enabled:incoming.enabled===true};for(const [field,[min,max]] of Object.entries(BAND_LOGO_RANGES))result[field]=clamp(incoming[field]??DEFAULT_BAND_LOGO[field],min,max);return result}
async function pollAudio(){try{const payload=await api('/api/audio/reactivity');const live=payload.available===true&&payload.capture_active===true;audioTarget=live?sanitizeAudioState(payload):neutralAudioState();audioLastReceivedAt=payload.available===true?performance.now():0;audioConnectionState=live?'live':payload.available===true?'capture-idle':'core-offline';document.documentElement.dataset.audioState=audioConnectionState}catch(error){audioTarget=neutralAudioState();audioLastReceivedAt=0;audioConnectionState='core-offline';document.documentElement.dataset.audioState=audioConnectionState}finally{audioPollTimer=setTimeout(pollAudio,50)}}
function syncCalibrationGainUI(){if(performance.now()<audioCalibrationEditingUntil)return;for(const prefix of ['A','B']){const gain=clamp(audioCalibration[`input${prefix}`]?.gain??1,0,32),input=els(`audioGain${prefix}`);input.value=gain;els(`audioGain${prefix}Value`).textContent=`${gain.toFixed(2)}×`;input.disabled=!audioCalibration.available}}
async function pollAudioCalibration(){try{audioCalibration=await api('/api/audio/calibration');syncCalibrationGainUI()}catch(error){audioCalibration={available:false,inputA:{gain:1},inputB:{gain:1}};syncCalibrationGainUI()}finally{audioCalibrationTimer=setTimeout(pollAudioCalibration,750)}}
function queueCalibrationGain(prefix,value){const gain=clamp(value,0,32);audioCalibrationEditingUntil=performance.now()+1200;els(`audioGain${prefix}Value`).textContent=`${gain.toFixed(2)}×`;clearTimeout(audioGainTimers[prefix]);audioGainTimers[prefix]=setTimeout(async()=>{try{audioCalibration=await api('/api/audio/calibration/manual',{method:'POST',body:JSON.stringify({input:prefix,field:'gain',value:gain})});audioCalibrationEditingUntil=0;syncCalibrationGainUI()}catch(error){console.error(error);audioCalibrationEditingUntil=0}},120)}
function smoothAudioValue(current,target,delta,rise=.09,fall=.45){const seconds=Math.max(0,delta)/1000,timeConstant=target>current?rise:fall,blend=1-Math.exp(-seconds/Math.max(.001,timeConstant));return current+(target-current)*blend}
function updateAudioSignals(delta,time){if(audioLastReceivedAt&&time-audioLastReceivedAt>500)audioTarget=neutralAudioState();for(const name of ['guitar_a','guitar_b']){for(const key of AUDIO_FIELDS){const rise=key==='attack'?.035:key==='sustain'?.22:.09,fall=key==='attack'?.24:key==='sustain'?1.1:.45;audioCurrent[name][key]=smoothAudioValue(audioCurrent[name][key],audioTarget[name][key],delta,rise,fall)}audioCurrent[name].silent=audioTarget[name].silent&&audioCurrent[name].intensity<.02}audioCurrent.interaction=smoothAudioValue(audioCurrent.interaction,audioTarget.interaction,delta,.25,.8)}
function rawMappingValue(source,signal){const a=signal.guitar_a,b=signal.guitar_b;if(source==='guitar_a')return a.intensity;if(source==='guitar_b')return b.intensity;if(source==='attack')return Math.max(a.attack,b.attack);if(source==='sustain')return Math.max(a.sustain,b.sustain);return clamp(Math.max(a.intensity,b.intensity)*.7+signal.interaction*.3,0,1)}
function updateMappingLevels(delta,signal=audioCurrent,tuning=audioTuning){for(const name of Object.keys(EFFECT_MAPPING_DEFS)){const config=tuning.effect_mappings[name],raw=rawMappingValue(config.source,signal),above=raw<=config.dead_zone?0:(raw-config.dead_zone)/(1-config.dead_zone),target=tuning.enabled&&config.enabled?clamp(above*config.sensitivity,0,1):0,timeConstant=(target>mappingLevels[name]?config.response_speed:config.decay_time)*(.35+config.smoothing*1.65);mappingLevels[name]=smoothAudioValue(mappingLevels[name],target,delta,timeConstant,timeConstant);mappingContributions[name]=mappingLevels[name]*config.max_contribution}}
function modulateEffects(base,signal=audioCurrent,tuning=audioTuning,contribution=mappingContributions){
  // Only the Color/Saturation mapping remains (liquid warp / edge glow / mirror
  // audio-mappings were deliberately removed - see AUDIT.md). The manual,
  // non-audio-reactive liquidIntensity/edgeGlow/mirrorH/mirrorV sliders in
  // DEFAULT_EFFECTS are untouched and still fully user-controllable.
  const fx={...base};if(!tuning.enabled)return fx;const color=contribution.color_saturation||0;fx.brightness=clamp(base.brightness*(1+color*.25),.4,1.8);fx.saturation=clamp(base.saturation+color*.72,0,2.5);fx.hue=clamp(base.hue+color*28,-180,180);return fx}
