function buildAudioTuningControls(){const root=els('audioMappingGroups');root.innerHTML='';for(const [name,definition] of Object.entries(EFFECT_MAPPING_DEFS)){const config=audioTuning.effect_mappings[name],section=document.createElement('section');section.className='audio-mapping';section.innerHTML=`<header><label><input id="audio-map-${name}-enabled" type="checkbox">${definition.label}</label><output id="audio-map-${name}-live">0.00</output></header><p>${definition.description}</p><label class="mapping-source"><span>Source</span><select id="audio-map-${name}-source">${Object.entries(AUDIO_SOURCES).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></label>`;const toggle=section.querySelector('input'),source=section.querySelector('select');toggle.checked=config.enabled;source.value=config.source;toggle.addEventListener('change',()=>{config.enabled=toggle.checked;audioTuning.active_preset='Custom';els('audioActivePreset').textContent='Custom';patchAudioTuningField(name,'enabled',config.enabled)});source.addEventListener('change',()=>{config.source=source.value;audioTuning.active_preset='Custom';els('audioActivePreset').textContent='Custom';patchAudioTuningField(name,'source',config.source)});for(const [field,[label,min,max,step]] of Object.entries(MAPPING_FIELDS)){const row=document.createElement('label');row.className='mapping-control';row.innerHTML=`<span>${label}</span><input id="audio-map-${name}-${field}" type="range" min="${min}" max="${max}" step="${step}"><output>${formatMappingValue(field,config[field])}</output>`;const input=row.querySelector('input'),output=row.querySelector('output');input.value=config[field];input.addEventListener('input',()=>{config[field]=+input.value;output.textContent=formatMappingValue(field,config[field]);audioTuning.active_preset='Custom';els('audioActivePreset').textContent='Custom';patchAudioTuningField(name,field,config[field])});section.append(row)}root.append(section)}syncAudioTuningSummary()}
function syncAudioTuningSummary(){els('audioTuningEnabled').checked=audioTuning.enabled;els('audioActivePreset').textContent=audioTuning.active_preset||'Custom';els('audioTuningSaveState').textContent='Tuning changed';for(const [name,config] of Object.entries(audioTuning.effect_mappings)){const toggle=els(`audio-map-${name}-enabled`),source=els(`audio-map-${name}-source`);if(toggle)toggle.checked=config.enabled;if(source)source.value=config.source;for(const field of Object.keys(MAPPING_FIELDS)){const input=els(`audio-map-${name}-${field}`);if(input){input.value=config[field];input.nextElementSibling.textContent=formatMappingValue(field,config[field])}}}}
function audioTuningPayload(){return{enabled:audioTuning.enabled,active_preset:audioTuning.active_preset,effect_mappings:audioTuning.effect_mappings}}
function debounceAudioTuning(){els('audioTuningSaveState').textContent='Saving tuning…';clearTimeout(audioTuningTimer);audioTuningTimer=setTimeout(saveAudioTuning,350)}
const mappingFieldTimers={};
function patchAudioTuningField(mapping,field,value){
  // Per-field save, not a full-object save: writes only this one value on the
  // server against its current in-memory state. Fixes the bug where a stale
  // full-object save from another tab/page-load silently reverted fields it
  // never touched (see AUDIT.md - multi-tab last-write-wins race).
  els('audioTuningSaveState').textContent='Saving tuning…';
  const key=mapping+'.'+field;
  clearTimeout(mappingFieldTimers[key]);
  mappingFieldTimers[key]=setTimeout(async()=>{
    try{
      const result=await api('/api/audio/tuning/field',{method:'POST',body:JSON.stringify({mapping,field,value})});
      audioTuning.last_modified=result.last_modified;
      audioTuning.active_preset=result.active_preset;
      if(audioTuning.effect_mappings[mapping])audioTuning.effect_mappings[mapping][field]=result.effect_mappings[mapping][field];
      els('audioActivePreset').textContent=audioTuning.active_preset||'Custom';
      els('audioTuningSaveState').textContent='Tuning saved';
    }catch(error){console.error(error);els('audioTuningSaveState').textContent='Tuning save failed'}
  },150);
}
