function setSignalMeter(id,value){const meter=els(id),numeric=clamp(value,0,1);meter.style.width=`${(numeric*100).toFixed(1)}%`;const output=els(`${id}Value`);if(output)output.textContent=numeric.toFixed(2)}
function updateGuitarDebug(prefix,channel){setSignalMeter(`audio${prefix}Level`,channel.input_level);setSignalMeter(`audio${prefix}Rms`,channel.rms_energy);setSignalMeter(`audio${prefix}Attack`,channel.attack);setSignalMeter(`audio${prefix}Sustain`,channel.sustain);const state=els(`audio${prefix}State`),silence=els(`audio${prefix}Silence`);state.className='';if(channel.attack>.08){state.textContent='ATTACK';state.className='attack'}else if(channel.sustain>.08){state.textContent='SUSTAIN';state.className='sustain'}else if(channel.intensity>.03)state.textContent='ACTIVE';else state.textContent='INACTIVE';silence.textContent=channel.silent?'YES':'NO';silence.classList.toggle('active',!channel.silent)}
