function updateAudioDebugUI(time){if(time-lastAudioUiPaint<80)return;lastAudioUiPaint=time;const a=audioCurrent.guitar_a,b=audioCurrent.guitar_b,status=els('audioCoreStatus');status.className='audio-status '+(audioConnectionState==='live'?'live':audioConnectionState==='capture-idle'?'idle':'offline');status.textContent=audioConnectionState==='live'?'AUDIO LIVE':audioConnectionState==='capture-idle'?'CAPTURE IDLE':'CORE OFFLINE';updateGuitarDebug('A',a);updateGuitarDebug('B',b);const energy=Math.max(a.intensity,b.intensity);setSignalMeter('performanceEnergy',energy);setSignalMeter('interactionMeter',audioCurrent.interaction);const interactionState=els('interactionState');interactionState.textContent=audioCurrent.interaction>.08?'BOTH GUITARS INTERACTING':'SOLO / IDLE';interactionState.classList.toggle('active',audioCurrent.interaction>.08);for(const name of Object.keys(EFFECT_MAPPING_DEFS)){const output=els(`audio-map-${name}-live`);if(output)output.textContent=mappingContributions[name].toFixed(2)}els('liveSaturation').textContent=Number(effectiveEffects.saturation||1).toFixed(2);const response=Math.max(...Object.values(mappingContributions)),modulationState=els('modulationState');modulationState.className='';if(!audioTuning.enabled)modulationState.textContent='MODULATION OFF';else if(audioConnectionState!=='live')modulationState.textContent='CORE OFFLINE';else if(response>.005){modulationState.textContent=`SHAPING VISUALS · ${response.toFixed(2)}`;modulationState.className='active'}else if(energy>.001)modulationState.textContent='BELOW MAPPING THRESHOLDS';else modulationState.textContent='WAITING FOR PLAYING';if(audioConnectionState==='live'){if(a.intensity>.08&&b.silent)markAudioTest('audioTestA','a');if(b.intensity>.08&&a.silent)markAudioTest('audioTestB','b');if(audioCurrent.interaction>.06)markAudioTest('audioTestBoth','both');const played=audioTestObserved.a||audioTestObserved.b||audioTestObserved.both,remaining=response;if(played&&a.silent&&b.silent&&remaining<.03)markAudioTest('audioTestSilence','silence')}}
