function makeRandom(initial){let state=(Number(initial)||1)>>>0;return()=>{state+=0x6D2B79F5;let value=state;value=Math.imul(value^value>>>15,value|1);value^=value+Math.imul(value^value>>>7,value|61);return((value^value>>>14)>>>0)/4294967296}}
function resetRandomStreams(){seed=Number(els('deterministicSeed').value)||1337;clipRandom=makeRandom(seed^0x9e3779b9);effectRandom=makeRandom(seed^0x85ebca6b);hueRandom=makeRandom(seed^0xc2b2ae35);hueCycleState=null;clipBag=[]}
function randomBetween(random,min,max){return min+(max-min)*random()}
function chooseNextCrossfade(){nextCrossfadeDuration=Math.round(randomBetween(clipRandom,1000,7000)/100)*100;els('transitionDuration').value=nextCrossfadeDuration;els('transitionDurationValue').textContent=`${(nextCrossfadeDuration/1000).toFixed(1)}s`;return nextCrossfadeDuration}
