const OPEN_GROUPS_BY_DEFAULT=new Set(['Color']);
function buildControls(){const root=els('effectGroups');root.innerHTML='';for(const [group,items] of Object.entries(GROUPS)){const section=document.createElement('details');section.className=`effect-group${group.startsWith('Experimental')?' experimental-group':''}`;section.open=OPEN_GROUPS_BY_DEFAULT.has(group);section.innerHTML=`<summary>${group.toUpperCase()}</summary>`;for(const [key,label,min,max,step,format] of items){const row=document.createElement('div');row.className=`effect-row${group.startsWith('Experimental')?' experimental':''}`;if(min===undefined){row.classList.add('boolean');row.innerHTML=`<input id="fx-${key}" type="checkbox"><label for="fx-${key}">${label}</label>`;const input=row.querySelector('input');input.checked=!!effects[key];input.addEventListener('change',()=>manualEffectChange(key,input.checked))}else{row.innerHTML=`<input id="on-${key}" type="checkbox" aria-label="Enable ${label}"><label for="fx-${key}">${label}</label><input id="fx-${key}" type="range" min="${min}" max="${max}" step="${step}"><output></output>`;const toggle=row.children[0],input=row.children[2],output=row.children[3];input.value=effects[key];toggle.checked=effects[key]!==DEFAULTS[key];output.textContent=format(effects[key]);toggle.addEventListener('change',()=>{manualEffectChange(key,toggle.checked?+input.value:DEFAULTS[key]);output.textContent=format(effects[key])});input.addEventListener('input',()=>{toggle.checked=true;output.textContent=format(+input.value);manualEffectChange(key,+input.value)})}section.append(row)}root.append(section)}}
