function syncControls(){for(const items of Object.values(GROUPS))for(const [key,,, , ,format] of items){const input=els(`fx-${key}`);if(!input)continue;if(input.type==='checkbox')input.checked=!!effects[key];else{input.value=effects[key];els(`on-${key}`).checked=effects[key]!==DEFAULTS[key];input.nextElementSibling.textContent=format(effects[key])}}applyEffectUI()}

