function syncTimelineUI(){els('currentEffectState').textContent=effectMorph?effectMorph.fromName:currentEffectName;els('upcomingEffectState').textContent=effectMorph?effectMorph.targetName:(upcomingPreset?.name||'—');const progress=effectMorph?Math.min(1,effectMorph.elapsed/effectMorph.duration):Math.min(1,effectHoldElapsed/effectHoldDuration);els('morphBar').style.width=`${effectMorph?progress*100:0}%`;els('morphProgress').textContent=effectPaused?'Effect timeline paused':effectLocked?'Effect state locked':effectMorph?`Morphing · ${Math.round(progress*100)}% · ${(Math.max(0,effectMorph.duration-effectMorph.elapsed)/1000).toFixed(1)}s`:`Holding · ${Math.max(0,(effectHoldDuration-effectHoldElapsed)/1000).toFixed(1)}s until morph`;els('presetBadge').textContent=effectMorph?`${effectMorph.fromName} → ${effectMorph.targetName}`:currentEffectName}

function refillClipBag(){clipBag=atoms.filter(atom=>atom.atom_id!==currentAtom?.atom_id).map(atom=>atom.atom_id);for(let index=clipBag.length-1;index>0;index--){const swap=Math.floor(clipRandom()*(index+1));[clipBag[index],clipBag[swap]]=[clipBag[swap],clipBag[index]]}const recent=new Set(history.slice(-5).map(atom=>atom.atom_id)),safeIndex=clipBag.findIndex(atomId=>!recent.has(atomId));if(safeIndex>=0&&clipBag.length){const last=clipBag.length-1;[clipBag[safeIndex],clipBag[last]]=[clipBag[last],clipBag[safeIndex]]}}
