function waitForMediaEvent(video,names,timeout,message){return new Promise((resolve,reject)=>{let timer=setTimeout(()=>finish(new Error(message)),timeout);const finish=error=>{clearTimeout(timer);for(const name of names)video.removeEventListener(name,ready);video.removeEventListener('error',failed);error?reject(error):resolve()};const ready=()=>finish();const failed=()=>finish(new Error('Media failed to load'));for(const name of names)video.addEventListener(name,ready,{once:true});video.addEventListener('error',failed,{once:true})})}
