function resizeCanvas(){const rect=canvas.getBoundingClientRect(),resolutionCap=Math.min(1,1920/Math.max(1,rect.width),1080/Math.max(1,rect.height)),ratio=Math.min(devicePixelRatio||1,1.5,resolutionCap),width=Math.max(640,Math.round(rect.width*ratio)),height=Math.max(360,Math.round(rect.height*ratio));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;resetMotionHistory(width,height)}}
