function applyEffectUI(fx=effectiveEffects){els('grain').style.opacity=fx.grain;els('vignette').style.opacity=fx.vignette;els('vhs').style.opacity=fx.vhs;const filters=[];if(fx.liquidIntensity>.001)filters.push('url("#liquidWarp")');if(fx.posterize)filters.push('url("#posterize")');if(fx.duotone)filters.push('url("#duotone")');if(fx.edgeGlow>.001||fx.sourceOpacity<.999)filters.push('url("#edgeGlow")');if(fx.hueCycle)filters.push(`saturate(${fx.saturation}) hue-rotate(${hueCycleValue()}deg)`);canvas.style.filter=filters.join(' ')||'none';const frequency=.004+fx.liquidScale*.032,turbulence=.7+fx.liquidTurbulence*1.4;els('liquidNoise').setAttribute('baseFrequency',`${frequency.toFixed(4)} ${(frequency*turbulence).toFixed(4)}`);els('liquidNoise').setAttribute('numOctaves',String(1+Math.round(fx.liquidTurbulence*2)));els('liquidDisplace').setAttribute('scale',String(fx.liquidIntensity*(18+fx.liquidTurbulence*58)));const phase=effectVisualTime/1000*fx.liquidSpeed,dx=Math.sin(phase*.53)*18*fx.liquidTurbulence+phase*fx.liquidDrift*7,dy=Math.cos(phase*.37)*12*fx.liquidTurbulence;els('liquidOffset').setAttribute('dx',dx.toFixed(2));els('liquidOffset').setAttribute('dy',dy.toFixed(2));const preBlur=1.55-fx.edgeSensitivity*1.15,gain=.55+fx.edgeSensitivity*2.7;els('edgePreBlur').setAttribute('stdDeviation',preBlur.toFixed(2));for(const id of ['edgeGainR','edgeGainG','edgeGainB'])els(id).setAttribute('slope',gain.toFixed(2));els('edgeDilate').setAttribute('radius',Math.max(.1,fx.edgeWidth*.26).toFixed(2));els('edgeBlur').setAttribute('stdDeviation',Math.max(.1,fx.edgeWidth*.52).toFixed(2));els('edgeFlood').setAttribute('flood-color',`hsl(${fx.edgeHue} 100% 68%)`);els('edgeGlowAlpha').setAttribute('slope',(fx.edgeGlow*1.55).toFixed(2));els('edgeSourceAlpha').setAttribute('slope',fx.sourceOpacity.toFixed(2));if(currentVideo)currentVideo.playbackRate=fx.speed;if(incomingVideo)incomingVideo.playbackRate=fx.speed}

