function rebuildMotionTrail(){const strength=Math.max(effectiveEffects.trailSmear,effectiveEffects.echo*.55);motionTrailCtx.save();motionTrailCtx.filter='none';motionTrailCtx.globalAlpha=1;motionTrailCtx.globalCompositeOperation='copy';motionTrailCtx.fillStyle='#000';motionTrailCtx.fillRect(0,0,motionTrail.width,motionTrail.height);if(strength>.01&&motionFrameCount>=3){const colorStrength=effectiveEffects.datamosh,available=Math.min(motionFrameCount-1,4+Math.round(strength*14)),phase=(effectVisualTime*.006)%360,currentIndex=(motionFrameCursor-1+motionFrames.length)%motionFrames.length,currentFrame=motionFrames[currentIndex];motionTrailCtx.globalCompositeOperation='screen';for(let age=available;age>=1;age--){const index=(motionFrameCursor-1-age+motionFrames.length)%motionFrames.length,frame=motionFrames[index],newness=1-age/(available+1),hue=(phase+age/available*300)*colorStrength,sepia=colorStrength*.9,saturation=1+colorStrength*5.2,softness=.2+age/available*.55;motionGhostCtx.save();motionGhostCtx.filter='none';motionGhostCtx.globalAlpha=1;motionGhostCtx.globalCompositeOperation='copy';motionGhostCtx.drawImage(frame,0,0,motionGhost.width,motionGhost.height);motionGhostCtx.globalCompositeOperation='difference';motionGhostCtx.drawImage(currentFrame,0,0,motionGhost.width,motionGhost.height);motionGhostCtx.restore();motionTrailCtx.globalAlpha=strength*(.1+newness*.13);motionTrailCtx.filter=`sepia(${sepia.toFixed(2)}) saturate(${saturation.toFixed(2)}) hue-rotate(${hue.toFixed(1)}deg) contrast(1.22) blur(${softness.toFixed(2)}px)`;motionTrailCtx.drawImage(motionGhost,0,0,motionTrail.width,motionTrail.height)}}motionTrailCtx.restore()}
function drawMotionTrail(){if(Math.max(effectiveEffects.trailSmear,effectiveEffects.echo*.55)<=.01||motionFrameCount<3)return;ctx.save();ctx.globalCompositeOperation='screen';ctx.filter='none';ctx.globalAlpha=1;ctx.drawImage(motionTrail,0,0,canvas.width,canvas.height);ctx.restore()}
function render(time){requestAnimationFrame(render);const delta=lastRenderTime?Math.min(100,time-lastRenderTime):0;lastRenderTime=time;updateEffectTimeline(delta);updateAudioSignals(delta,time);updateMappingLevels(delta,audioCurrent,audioTuning);effectiveEffects=modulateEffects(effects,audioCurrent,audioTuning,mappingContributions);updateAudioDebugUI(time);if(clipPlaying&&currentVideo&&!clipTransition&&!transitionPending&&time>=playbackRecoveryAt&&(currentVideo.paused||currentVideo.ended)){playbackRecoveryAt=time+1000;els('clipHealthBadge').textContent='RECOVERING';if(currentVideo.ended)goNext();else safePlay(currentVideo).then(started=>{els('clipHealthBadge').textContent=started?'PLAYING':'RECOVERING';if(!started&&!transitionPending&&!clipTransition)goNext()})}if(time-lastPaint<16)return;lastPaint=time;resizeCanvas();ctx.save();ctx.fillStyle='#000';ctx.fillRect(0,0,canvas.width,canvas.height);if(clipTransition){if(clipPlaying)clipTransition.elapsed+=delta;const mix=Math.min(1,clipTransition.elapsed/clipTransition.duration);drawSource(currentVideo,1-mix);drawSource(incomingVideo,mix);if(mix>=1)finishClipTransition()}else drawSource(currentVideo,1);ctx.restore();if(captureMotionFrame(time))rebuildMotionTrail();drawMotionTrail();applyEffectUI(effectiveEffects)}
function startRender(){if(renderStarted)return;renderStarted=true;requestAnimationFrame(render)}

function updateInfo(atom=currentAtom){if(!atom)return;els('atomId').textContent=atom.atom_id;els('description').textContent=atom.description||atom.primary_subject||'';els('timestamps').textContent=`${atom.start_timestamp} → ${atom.end_timestamp} · ${Number(atom.duration_seconds).toFixed(1)}s`;els('tier').textContent=atom.tier;els('motif').textContent=atom.motif_category;els('mood').textContent=atom.mood;els('energy').textContent=Number(atom.energy_level).toFixed(2);els('motion').textContent=Number(atom.motion_intensity).toFixed(2);els('synergy').textContent=Number(atom.procedural_synergy_score).toFixed(2);els('tags').innerHTML=[...(atom.content_tags||[]),...(atom.collections||[])].slice(0,14).map(tag=>`<span>${escapeHtml(tag)}</span>`).join('');els('groupBadge').textContent='UNIFORM RANDOM · SHUFFLED DECK'}
function toggleClips(){clipPlaying=!clipPlaying;els('clipPause').textContent=clipPlaying?'Pause clips':'Resume clips';els('clipPausedBadge').style.display=clipPlaying?'none':'block';els('clipHealthBadge').textContent=clipPlaying?'RECOVERING':'PAUSED';for(const video of [currentVideo,incomingVideo])if(video){if(clipPlaying)safePlay(video).then(started=>{if(video===currentVideo&&!clipTransition)els('clipHealthBadge').textContent=started?'PLAYING':'RECOVERING'});else video.pause()}}
function toggleEffects(){effectPaused=!effectPaused;els('effectPause').textContent=effectPaused?'Resume effects':'Pause effects';els('effectPause').classList.toggle('active',effectPaused);syncTimelineUI();debounceSession()}
function toggleLock(){effectLocked=!effectLocked;if(effectLocked&&effectMorph){effects={...effects};currentEffectName='Locked blend';effectMorph=null;booleanMorph=null}els('effectLock').textContent=effectLocked?'Unlock state':'Lock state';els('effectLock').classList.toggle('active',effectLocked);syncTimelineUI();debounceSession()}
function restartSeededTimelines(){resetRandomStreams();chooseNextCrossfade();history=currentAtom?[currentAtom]:[];historyPos=history.length-1;cancelMorph(currentEffectName);scheduleHold();syncTimelineUI();debounceSession()}

async function refreshAtomLibrary(){setSave('Saving');try{await api('/api/library/refresh',{method:'POST',body:'{}'});const data=await api('/api/exploration/bootstrap');atoms=data.atoms;clipBag=[];els('approvedCount').textContent=data.approved_count;const replacement=atoms.find(atom=>atom.atom_id===currentAtom?.atom_id);if(replacement){currentAtom=replacement;if(currentVideo)currentVideo._atom=replacement;history=history.map(old=>atoms.find(atom=>atom.atom_id===old.atom_id)||old);updateInfo()}else if(atoms.length){disposeVideo(currentVideo);disposeVideo(incomingVideo);currentVideo=incomingVideo=null;clipTransition=null;transitionPending=false;history=[];historyPos=-1;await setInitial(atoms[0])}setSave('Saved');els('refreshLibrary').textContent='Library refreshed';setTimeout(()=>els('refreshLibrary').textContent='Refresh Atom Library',1800)}catch(error){console.error(error);setSave('Save failed')}}
async function init(){try{const data=await api('/api/exploration/bootstrap');atoms=data.atoms;presets=data.presets;audioTuning=sanitizeAudioTuning(data.audio_tuning||DEFAULT_AUDIO_TUNING);audioTuningPresets=data.audio_tuning_presets||[];currentEffectName=data.session.current_preset||'Queen Cosmic Dream';effects=sanitizeEffects(data.session.effects);effectiveEffects={...effects};if(currentEffectName==='Mirror Bloom')effects.mirrorOverlay=true;if(currentEffectName==='Prismatic Ritual')effects.hueCycle=true;effectPaused=!!data.session.effect_timeline_paused;effectLocked=!!data.session.effect_locked;playbackQuality=data.session.playback_quality==='original'?'original':'proxy';seed=data.session.deterministic_seed||1337;els('approvedCount').textContent=data.approved_count;els('effectDurationMin').value=data.session.effect_duration_min||15;els('effectDurationMax').value=data.session.effect_duration_max||45;els('morphDurationMin').value=data.session.morph_duration_min||5;els('morphDurationMax').value=data.session.morph_duration_max||15;els('deterministicSeed').value=seed;syncQualityUI();buildControls();syncControls();buildAudioTuningControls();updateAudioTuningPresetSelect();els('audioTuningSaveState').textContent='Tuning saved';updatePresetSelect();els('presetSelect').value=presets.some(p=>p.name===currentEffectName)?currentEffectName:'';resetRandomStreams();scheduleHold();pollAudio();pollAudioCalibration();if(effectPaused){els('effectPause').textContent='Resume effects';els('effectPause').classList.add('active')}if(effectLocked){els('effectLock').textContent='Unlock state';els('effectLock').classList.add('active')}syncTimelineUI();const first=atoms.find(a=>a.atom_id===data.session.current_atom_id)||chooseWeighted();await setInitial(first)}catch(error){console.error(error);els('atomId').textContent='Sandbox failed to load';els('description').textContent=error.message;setSave('Save failed')}}

els('clipPause').addEventListener('click',toggleClips);els('skip').addEventListener('click',goNext);els('previous').addEventListener('click',goPrevious);els('effectPause').addEventListener('click',toggleEffects);els('effectLock').addEventListener('click',toggleLock);els('nextMorph').addEventListener('click',()=>beginNextMorph());els('resetSeed').addEventListener('click',restartSeededTimelines);els('presetSelect').addEventListener('change',event=>applyPresetImmediate(event.target.value));els('randomPreset').addEventListener('click',()=>{selectUpcoming();beginNextMorph()});els('resetEffects').addEventListener('click',()=>{cancelMorph('Custom');effects={...DEFAULTS};els('presetSelect').value='';syncControls();scheduleHold();syncTimelineUI();debounceSession()});
els('fullscreen').addEventListener('click',toggleFullscreen);document.addEventListener('fullscreenchange',syncFullscreenUI);document.addEventListener('webkitfullscreenchange',syncFullscreenUI);
els('qualityMode').addEventListener('change',event=>setPlaybackQuality(event.target.value));
els('refreshLibrary').addEventListener('click',refreshAtomLibrary);
els('savePreset').addEventListener('click',async()=>{const name=els('presetName').value.trim();if(!name){els('presetName').focus();return}setSave('Saving');try{const result=await api('/api/exploration/presets',{method:'POST',body:JSON.stringify({name,effects,description:'Saved during independent-timeline exploration.'})});presets=result.presets;currentEffectName=name;updatePresetSelect();els('presetSelect').value=name;els('presetName').value='';scheduleHold();syncTimelineUI();setSave('Saved')}catch(error){console.error(error);setSave('Save failed')}});
els('audioTuningEnabled').addEventListener('change',event=>{audioTuning.enabled=event.target.checked;audioTuning.active_preset='Custom';syncAudioTuningSummary();debounceAudioTuning()});
for(const prefix of ['A','B'])els(`audioGain${prefix}`).addEventListener('input',event=>queueCalibrationGain(prefix,event.target.value));
els('loadAudioTuningPreset').addEventListener('click',loadAudioTuningPreset);els('saveAudioTuningPreset').addEventListener('click',saveNamedAudioTuningPreset);els('resetAudioTest').addEventListener('click',resetAudioTest);
for(const id of ['effectDurationMin','effectDurationMax','morphDurationMin','morphDurationMax']){els(id).addEventListener('input',debounceSession);els(id).addEventListener('change',()=>{scheduleHold();debounceSession()})}els('deterministicSeed').addEventListener('input',()=>{seed=Number(els('deterministicSeed').value)||1337;debounceSession()});els('deterministicSeed').addEventListener('change',restartSeededTimelines);window.addEventListener('resize',resizeCanvas);window.addEventListener('keydown',event=>{if(['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName))return;if(event.code==='Space'){event.preventDefault();toggleClips()}else if(event.key==='ArrowRight')goNext();else if(event.key==='ArrowLeft')goPrevious();else if(event.key.toLowerCase()==='e')toggleEffects();else if(event.key.toLowerCase()==='f')toggleFullscreen();else if(event.key.toLowerCase()==='m')beginNextMorph()});window.addEventListener('beforeunload',()=>{navigator.sendBeacon('/api/exploration/session',new Blob([JSON.stringify(sessionPayload())],{type:'application/json'}));navigator.sendBeacon('/api/audio/tuning',new Blob([JSON.stringify(audioTuningPayload())],{type:'application/json'}))});
init();
